// spec: specs/delivery.md §13 · кейс .qa/tests/delivery/dlv-17-delivery-note-bad-check-digit.md
// seed: tests/seed.admin.spec.ts
// #1ee7e8 (באג, עבר QA 28.10, commit 69f5029): מק"ט 8/12/13 цифр с неверной контрольной цифрой больше не печатается как Code128.
//   Экран: под מק"ט — «ספרת הביקורת של המק״ט שגויה — אין ברקוד», без штрихкода; печать — только текст מק"ט, без штрихкода.
//   Регресс #f43d23: верный EAN-13 (5710840209437 в #504) — штрихкод есть.
// Данные — существующие заказы, только чтение: #665 (נדחתה, QA-AUTO-ean-1307-BAD, 5710840209438), #504. → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const NOTE_665 = '0ea59ef3-e3c3-492d-96b0-841299e46761';
const NOTE_504 = '6f797bf5-1ef8-44eb-8ad5-073e0b0f341e';
const BAD = '5710840209438';
const GOOD = '5710840209437';
const MSG = 'ספרת הביקורת של המק״ט שגויה — אין ברקוד';

async function open(page: Page, id: string, no: number) {
  await page.goto(`/delivery/${id}`);
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
}

/** Строка экранной таблицы с данным מק"ט: видимые штрихкоды и видимое сообщение. */
const screenRow = (page: Page, sku: string, msg: string) => page.evaluate(({ sku, msg }) => {
  const t = [...document.querySelectorAll('table')].find((x) => !x.classList.contains('pd-table') && x.checkVisibility()) as HTMLTableElement;
  const r = [...t.tBodies[0].rows].find((x) => x.textContent!.includes(sku));
  if (!r) return null;
  return {
    barcodes: [...r.querySelectorAll('svg[data-barcode]')].filter((s) => s.checkVisibility() && s.getBoundingClientRect().width > 0).length,
    msgVisible: [...r.querySelectorAll('span')].filter((s) => s.childElementCount === 0 && s.textContent!.trim() === msg && s.checkVisibility()).length,
  };
}, { sku, msg });

test.describe('delivery — מק"ט עם ספרת ביקורת שגויה: אין ברקוד בתעודה (#1ee7e8)', () => {
  test('#665: במסך «ספרת הביקורת של המק״ט שגויה — אין ברקוד» ובלי ברקוד (1440 ו-390); בהדפסה רק טקסט המק"ט #1ee7e8 @desktop @delivery @prod-safe', async ({ page }) => {
    await open(page, NOTE_665, 665);
    await expect(page.getByText(BAD).first()).toBeAttached({ timeout: 20_000 }); // таблица товаров загрузилась
    for (const w of [1440, 390]) {
      await page.setViewportSize({ width: w, height: 900 });
      await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
      const r = await screenRow(page, BAD, MSG);
      expect(r, `${w}: строка с ${BAD}`).not.toBeNull();
      expect(r!.barcodes, `${w}: у ${BAD} нет штрихкода`).toBe(0);
      expect(r!.msgVisible, `${w}: видно «${MSG}» один раз`).toBe(1);
    }
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.emulateMedia({ media: 'print' });
    const p = await page.evaluate((sku) => {
      const t = document.querySelector('table.pd-table') as HTMLTableElement;
      const line = [...t.querySelectorAll('tbody.pd-line')].find((b) => b.textContent!.includes(sku))!;
      return { visible: t.checkVisibility(), text: (line as HTMLElement).innerText, svgs: line.querySelectorAll('svg[data-barcode]').length };
    }, BAD);
    expect(p.visible, 'печатная таблица видна').toBe(true);
    expect(p.text, 'в печати — текст מק"ט').toContain(BAD);
    expect(p.svgs, 'в печати — без штрихкода').toBe(0);
    await page.emulateMedia({ media: 'screen' });
  });

  test('רגרסיה #504: EAN-13 תקין — יש ברקוד ואין הודעת ספרת ביקורת #1ee7e8 #f43d23 @desktop @delivery @prod-safe', async ({ page }) => {
    await open(page, NOTE_504, 504);
    await expect(page.locator('svg[data-barcode]').first()).toBeAttached({ timeout: 20_000 });
    const r = await screenRow(page, GOOD, MSG);
    expect(r, `строка с ${GOOD}`).not.toBeNull();
    expect(r!.barcodes, `${GOOD} — 1 штрихкод`).toBe(1);
    expect(r!.msgVisible, 'без сообщения о контрольной цифре').toBe(0);
    await expect(page.getByText(MSG)).toHaveCount(0);
  });
});
